    border-radius: 4px;
    font-weight: 500;
}

.pfd-telemetry {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.telemetry-row {
    display: flex;
    justify-content: space-between;
    gap: 0.5rem;
}

.telemetry-item {
    padding: 0.5rem;
    background: var(--light-color);
    border-radius: 4px;
