        # Get MAVLink connection
        mavlink_conn = get_mavlink_connection()

        if not mavlink_conn:
            result = {
                'success': False,
                'command': command,
                'error': 'No MAVLink connection available',
                'timestamp': time.time()
            }
        else:
            # Process the flight command
            result = process_flight_command(data, mavlink_conn, log_command_action)

